import re
from decimal import Decimal, ROUND_HALF_UP

_NUM = r"\d+(?:\.\d+)?"

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_BARE_INT = re.compile(r"\d+")
_COMPONENT = re.compile(r"(" + _NUM + r")\s*([A-Za-z]+)")
_ISO = re.compile(
    r"P"
    r"(?:(?P<W>" + _NUM + r")W)?"
    r"(?:(?P<D>" + _NUM + r")D)?"
    r"(?:T"
    r"(?:(?P<H>" + _NUM + r")H)?"
    r"(?:(?P<M>" + _NUM + r")M)?"
    r"(?:(?P<S>" + _NUM + r")S)?"
    r")?",
    re.IGNORECASE,
)
_CLOCK = re.compile(r"\d+(?::\d+){1,2}(?:\.\d+)?")


def _round(value: Decimal) -> int:
    return int(value.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def _parse_iso(text: str) -> int:
    m = _ISO.fullmatch(text)
    if not m or text.upper() in ("P", "PT") or text.endswith("T"):
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    total = Decimal(0)
    weights = {"W": 604800, "D": 86400, "H": 3600, "M": 60, "S": 1}
    for key, factor in weights.items():
        value = m.group(key)
        if value is not None:
            total += Decimal(value) * factor
    return _round(total)


def _parse_clock(text: str) -> int:
    parts = text.split(":")
    total = Decimal(0)
    for part in parts[:-1]:
        total = total * 60 + Decimal(part)
    total = total * 60 + Decimal(parts[-1])
    return _round(total)


def _parse_components(text: str) -> int:
    pos = 0
    total = Decimal(0)
    n = len(text)
    while pos < n:
        while pos < n and text[pos].isspace():
            pos += 1
        if pos >= n:
            break
        m = _COMPONENT.match(text, pos)
        if not m:
            raise ValueError(f"invalid duration component at {pos}: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {m.group(2)!r}")
        total += Decimal(m.group(1)) * _UNITS[unit]
        pos = m.end()
    return _round(total)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")
    if _BARE_INT.fullmatch(s):
        return int(s)
    if s[0] in "Pp":
        return _parse_iso(s)
    if ":" in s:
        if not _CLOCK.fullmatch(s):
            raise ValueError(f"invalid clock duration: {text!r}")
        return _parse_clock(s)
    return _parse_components(s)

